sections.css:
.stack {
  --gap: var(--spacing-400, 1rem);
  gap: var(--gap);
  flex-direction: column;
  display: flex;
}
.typography-microcopy-xs {
  font-family: var(--typography-microcopy-xs-font-family);
  font-size: var(--typography-microcopy-xs-font-size);
  font-weight: var(--typography-microcopy-xs-font-weight);
  line-height: var(--typography-microcopy-xs-line-height);
  letter-spacing: var(--typography-microcopy-xs-letter-spacing);
}
.typography-label-sm-strong {
  font-family: var(--typography-label-sm-strong-font-family);
  font-size: var(--typography-label-sm-strong-font-size);
  font-weight: var(--typography-label-sm-strong-font-weight);
  line-height: var(--typography-label-sm-strong-line-height);
  letter-spacing: var(--typography-label-sm-strong-letter-spacing);
}
.typography-microcopy-md {
  font-family: var(--typography-microcopy-md-font-family);
  font-size: var(--typography-microcopy-md-font-size);
  font-weight: var(--typography-microcopy-md-font-weight);
  line-height: var(--typography-microcopy-md-line-height);
  letter-spacing: var(--typography-microcopy-md-letter-spacing);
}
.typography-microcopy-xs-strong {
  font-family: var(--typography-microcopy-xs-strong-font-family);
  font-size: var(--typography-microcopy-xs-strong-font-size);
  font-weight: var(--typography-microcopy-xs-strong-font-weight);
  line-height: var(--typography-microcopy-xs-strong-line-height);
  letter-spacing: var(--typography-microcopy-xs-strong-letter-spacing);
}
.typography-body-md {
  font-family: var(--typography-body-md-font-family);
  font-size: var(--typography-body-md-font-size);
  font-weight: var(--typography-body-md-font-weight);
  line-height: var(--typography-body-md-line-height);
  letter-spacing: var(--typography-body-md-letter-spacing);
}
.esa-button {
  --_btn-pad-y: var(--spacing-300, 0.75rem);
  --_btn-padding-x: var(--spacing-300, 0.75rem);
  --_btn-radius: var(--button-radius-md, 0.5rem);
  --_accent: var(--color-background-brand, #46a758);
  --_accent-hover: var(--color-background-brand-hover, #3e9b4f);
  --_on: var(--color-content-default-knockout, #fcfcfc);
  --_accent-text: var(--_accent);
  --_btn-tint-hover: color-mix(in srgb, var(--_accent) 8%, transparent);
  --_btn-tint-active: color-mix(in srgb, var(--_accent) 14%, transparent);
  display: inline-block;
}
.esa-button--sm {
  --_btn-pad-y: var(--spacing-250, 0.625rem);
  --_btn-padding-x: var(--spacing-250, 0.625rem);
  --_btn-radius: var(--button-radius-sm, 4px);
}
.esa-button--variant-danger {
  --_accent: var(--color-background-utility-danger);
  --_accent-hover: var(--color-background-utility-danger-hover);
  --_accent-text: var(--color-content-utility-danger);
}
.esa-button__native {
  justify-content: center;
  align-items: center;
  gap: var(--spacing-200, 8px);
  width: 100%;
  padding-block: var(--_btn-pad-y);
  padding-inline: var(--_btn-padding-x);
  border: var(--border-width-default, 1px) solid transparent;
  border-radius: var(--_btn-radius);
  cursor: pointer;
  transition:
    background var(--transition-fast, 0.15s ease),
    border-color var(--transition-fast, 0.15s ease);
  -webkit-appearance: none;
  appearance: none;
  text-decoration: none;
  display: inline-flex;
}
.esa-button--appearance-fill .esa-button__native {
  background: var(--_accent);
  color: var(--_on);
  border-color: var(--_accent-border, transparent);
}
.esa-button__label {
  white-space: nowrap;
}
.esa-button--appearance-outline .esa-button__native,
.esa-button--appearance-dashed .esa-button__native {
  color: var(--_accent-text);
  border-color: var(--_accent);
  background: 0 0;
}
.esa-button--variant-ghost .esa-button__native {
  color: var(--color-content-default, #202020);
  background: 0 0;
  border-color: #0000;
}
.esa-button--variant-ghost.esa-button--appearance-outline .esa-button__native,
.esa-button--variant-ghost.esa-button--appearance-dashed .esa-button__native {
  border-color: var(--color-border-default, #cecece);
}
.esa-button--variant-chrome .esa-button__native {
  color: inherit;
  background: 0 0;
  border-color: #0000;
}
.esa-button--icon-only .esa-button__native {
  padding-inline: var(--_btn-pad-y);
  aspect-ratio: 1;
}
.esa-button--variant-primary {
  --_accent-text: var(--color-content-brand);
}
.bcn-status-chip {
  align-items: center;
  gap: var(--spacing-150);
  padding: 2px var(--spacing-250);
  border-radius: var(--radius-full);
  font-size: var(--font-size-100);
  font-weight: var(--typography-font-weight-semibold);
  white-space: nowrap;
  background: color-mix(in srgb, var(--_chip) 16%, transparent);
  color: color-mix(in srgb, var(--_chip) 72%, #1a1a1a);
  display: inline-flex;
}
.bcn-status-chip__dot {
  border-radius: var(--radius-full);
  background: var(--_chip);
  flex-shrink: 0;
  width: 8px;
  height: 8px;
}
.bcn-key-value {
  flex-direction: column;
  gap: 2px;
  display: flex;
}
.bcn-key-value__key {
  font-size: var(--typography-label-md-font-size);
  font-weight: var(--typography-font-weight-medium);
  color: var(--form-label-color);
}
.bcn-key-value__val {
  font-size: var(--typography-label-md-font-size);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.esa-collapsible {
  border: var(--border-width-default, 1px) solid var(--color-border-default, #cecece);
  border-radius: var(--radius-md, 0.5rem);
  background: var(--color-background-elevation-raised, #fcfcfc);
}
.esa-collapsible--flush {
  background: 0 0;
  border: none;
  border-radius: 0;
}
.esa-collapsible__summary {
  align-items: center;
  gap: var(--spacing-200, 0.5rem);
  padding: var(--spacing-300, 0.75rem) var(--spacing-400, 1rem);
  color: var(--color-content-default, #202020);
  cursor: pointer;
  list-style: none;
  display: flex;
}
.esa-collapsible--flush > .esa-collapsible__summary,
.esa-collapsible--flush > .esa-collapsible__body {
  padding-inline: 0;
}
.esa-collapsible__summary .esa-icon {
  color: var(--color-content-default-secondary, #646464);
  flex-shrink: 0;
}
.esa-collapsible__summary:after {
  content: "";
  border-right: 2px solid var(--color-content-default-secondary, #646464);
  border-bottom: 2px solid var(--color-content-default-secondary, #646464);
  width: 8px;
  height: 8px;
  margin-left: auto;
  transition: transform 0.15s;
  transform: rotate(-45deg);
}
.esa-badge {
  --_badge-bg: var(--badge-bg, var(--color-background-brand, #46a758));
  --_badge-text: var(--badge-text-color, var(--color-content-default-knockout, #fcfcfc));
  --_badge-padding-y: var(--spacing-150, 0.375rem);
  --_badge-padding-x: var(--spacing-200, 0.5rem);
  min-width: calc(1lh + 2 * var(--_badge-padding-y));
  padding-block: var(--_badge-padding-y);
  padding-inline: var(--_badge-padding-x);
  border-radius: var(--radius-chip, var(--radius-sm, 0.25rem));
  background: var(--_badge-bg);
  color: var(--_badge-text);
  white-space: nowrap;
  box-sizing: border-box;
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.esa-badge--sm {
  --_badge-padding-y: var(--spacing-100, 0.25rem);
  --_badge-padding-x: var(--spacing-150, 0.375rem);
}
.esa-badge--secondary {
  --_badge-bg: var(--color-background-brand-muted, #e9f6e9);
  --_badge-text: var(--color-content-on-brand-muted, #203c25);
}
.esa-collapsible[open] > .esa-collapsible__summary:after {
  transform: rotate(45deg);
}
.esa-collapsible__body {
  gap: var(--spacing-400, 1rem);
  padding: 0 var(--spacing-400, 1rem) var(--spacing-400, 1rem);
  flex-direction: column;
  display: flex;
}
.spec {
  max-width: 1480px;
  padding: var(--spacing-700) var(--spacing-500) var(--spacing-800);
  gap: var(--spacing-700);
  flex-direction: column;
  margin: 0 auto;
  display: flex;
}
.spec__head {
  gap: var(--spacing-300);
  flex-direction: column;
  display: flex;
}
.spec__title {
  font-family: var(--font-decorative);
  font-size: 2rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
}
.spec__intro {
  max-width: 86ch;
  font-size: var(--font-size-200, 1rem);
  color: var(--color-content-default-secondary);
  margin: 0;
  line-height: 1.6;
}
.spec__intro strong {
  color: var(--color-content-default);
  font-weight: var(--typography-font-weight-semibold);
}
.v2 {
  gap: var(--spacing-500);
  flex-direction: column;
  display: flex;
}
.v2__head {
  gap: var(--spacing-300);
  flex-direction: column;
  display: flex;
}
.v2__title {
  font-size: 1.5rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
}
.v2__changes {
  gap: var(--spacing-200);
  flex-direction: column;
  max-width: 86ch;
  margin: 0;
  padding-left: 1.25rem;
  display: flex;
}
.v2__changes li {
  color: var(--color-content-default-secondary);
  font-size: 1rem;
  line-height: 1.55;
}
.v2__changes strong {
  color: var(--color-content-default);
  font-weight: var(--typography-font-weight-semibold);
}
.v2__pair {
  gap: var(--spacing-500);
  grid-template-columns: repeat(auto-fit, minmax(360px, 1fr));
  align-items: start;
  max-width: 1000px;
  display: grid;
}
.mockup {
  gap: var(--spacing-200);
  flex-direction: column;
  margin: 0;
  display: flex;
}
.v2__pair .mockup {
  justify-self: center;
  width: 100%;
  max-width: 460px;
}
.mockup__case {
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default-secondary);
  line-height: 1.5;
}
.drawer {
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-300);
  overflow: hidden;
  box-shadow: 0 12px 32px #0000001a;
}
.drawer__head {
  padding: var(--spacing-400);
  border-bottom: 1px solid var(--color-border-default);
  flex-direction: column;
  gap: 2px;
  display: flex;
}
.drawer__headrow {
  align-items: center;
  gap: var(--spacing-300);
  display: flex;
}
.drawer__title {
  font-size: var(--font-size-400);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
}
.bcn-status-chip[data-status="provisional-block"],
.bcn-status-chip[data-status="provisional-block"] .bcn-status-chip__dot {
  background: var(--color-background-elevation-raised);
  box-shadow: inset 0 0 0 1.5px var(--st-provisional-block);
}
.drawer__sub {
  color: var(--color-content-default-secondary);
  margin: 0;
  font-size: 0.875rem;
}
.band {
  gap: var(--spacing-200) var(--spacing-300);
  padding: var(--spacing-250) var(--spacing-400);
  background: var(--color-background-default);
  border-bottom: 1px solid var(--color-border-default);
  grid-template-columns: repeat(3, 1fr);
  display: grid;
}
.drawer__body {
  gap: var(--spacing-400);
  padding: var(--spacing-400);
  flex-direction: column;
  display: flex;
}
.decide {
  gap: var(--spacing-200);
  padding: var(--spacing-250) var(--spacing-300);
  border-radius: var(--radius-200);
  background: var(--color-background-default);
  border: 1px solid var(--color-border-default);
  flex-direction: column;
  display: flex;
}
.decide--prov {
  background: color-mix(in srgb, var(--st-provisional-block) 6%, transparent);
  border-color: color-mix(in srgb, var(--st-provisional-block) 45%, transparent);
  --color-background-utility-danger: var(--st-provisional-block);
}
.decide__line {
  font-size: 0.9375rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
  line-height: 1.45;
}
.decide__line--fact {
  align-items: center;
  gap: var(--spacing-250);
  flex-wrap: wrap;
  display: flex;
}
.decide--prov .decide__line {
  color: color-mix(in srgb, var(--st-provisional-block) 72%, #1a1a1a);
}
.obs-id {
  font-family: var(--typography-font-family-mono);
  padding: 1px var(--spacing-200);
  border-radius: var(--radius-100);
  background: var(--color-background-elevation-raised);
  border: 1px solid color-mix(in srgb, var(--st-provisional-block) 45%, transparent);
  color: color-mix(in srgb, var(--st-provisional-block) 72%, #1a1a1a);
  white-space: nowrap;
  flex-shrink: 0;
  font-size: 0.8125rem;
  font-weight: 500;
}
.decide__actions {
  justify-content: flex-end;
  gap: var(--spacing-200);
  display: flex;
}
.drawer__section {
  align-items: center;
  gap: var(--spacing-200);
  margin: 0 0 var(--spacing-300);
  font-size: 0.9375rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  display: flex;
}
.drawer__section .esa-icon {
  color: var(--color-content-default-secondary);
  flex-shrink: 0;
}
.board {
  gap: var(--spacing-200);
  grid-template-columns: 1fr 1fr;
  display: grid;
}
.board__cell--btn {
  cursor: pointer;
  text-align: left;
  border: 1px solid var(--color-border-default-subtle);
  background: var(--color-background-elevation-raised);
  width: 100%;
  font-family: inherit;
  transition:
    border-color 0.12s,
    background 0.12s;
}
.board__cell {
  align-items: flex-start;
  gap: var(--spacing-150);
  padding: var(--spacing-250) var(--spacing-300);
  border: 1px solid var(--color-border-default-subtle);
  border-radius: var(--radius-200);
  background: var(--color-background-elevation-raised);
  flex-direction: column;
  display: flex;
}
.board__cellhead {
  align-items: center;
  gap: var(--spacing-150);
  width: 100%;
  display: flex;
}
.board__dim {
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.board__cellhead .board__dim {
  flex: 1;
  min-width: 0;
}
.board__chev {
  color: var(--color-content-default-tertiary);
  display: inline-flex;
}
.board__meta {
  color: var(--color-content-default-tertiary);
  font-size: 0.8125rem;
}
.unreviewed {
  padding: 2px var(--spacing-250);
  border: 1px dashed var(--color-border-default-strong);
  border-radius: var(--radius-full);
  font-size: var(--font-size-100);
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-tertiary);
  white-space: nowrap;
  align-items: center;
  display: inline-flex;
}
.drawer__more {
  flex-direction: column;
  display: flex;
}
.drawer__more .esa-collapsible + .esa-collapsible {
  border-top: 1px solid var(--color-border-default-subtle);
}
.drawer__foot {
  justify-content: flex-end;
  gap: var(--spacing-200);
  padding: var(--spacing-300) var(--spacing-400);
  border-top: 1px solid var(--color-border-default);
  background: var(--color-background-elevation-raised);
  display: flex;
}
.decide__row {
  align-items: center;
  gap: var(--spacing-250);
  display: flex;
}
.decide__row--warn .esa-icon {
  color: color-mix(in srgb, var(--st-blocked) 72%, #1a1a1a);
  flex-shrink: 0;
}
.decide__warntext {
  min-width: 0;
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-semibold);
  color: color-mix(in srgb, var(--st-blocked) 72%, #1a1a1a);
  flex: 1;
  line-height: 1.45;
}
.v2__sub {
  margin: var(--spacing-300) 0 0;
  font-size: 1.1875rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.stack {
  width: 100%;
  max-width: 540px;
  position: relative;
}
.stack__parent {
  width: calc(100% - 72px);
  position: relative;
}
.band--4 {
  grid-template-columns: repeat(4, 1fr);
}
.band__alert {
  font-size: var(--typography-label-md-font-size);
  font-weight: var(--typography-font-weight-semibold);
  color: color-mix(in srgb, var(--st-blocked) 72%, #1a1a1a);
}
.decide--blocked {
  background: color-mix(in srgb, var(--st-blocked) 10%, transparent);
  border-color: color-mix(in srgb, var(--st-blocked) 30%, transparent);
}
.decide--blocked .decide__line {
  color: color-mix(in srgb, var(--st-blocked) 72%, #1a1a1a);
}
.board__cell--btn[data-active] {
  border-color: var(--color-background-brand);
  box-shadow: inset 0 0 0 1px var(--color-background-brand);
  background: var(--color-background-brand-subtle);
}
.stack__parent:after {
  content: "";
  border-radius: var(--radius-300);
  z-index: 4;
  pointer-events: none;
  background: #0d111438;
  position: absolute;
  inset: 0;
}
.stack__child {
  z-index: 5;
  flex-direction: column;
  width: calc(100% - 72px);
  display: flex;
  position: absolute;
  top: 0;
  bottom: 0;
  right: 0;
  box-shadow: -16px 0 40px #00000038;
}
.drawer__close {
  color: var(--color-content-default-secondary);
  margin-left: auto;
}
.stack__child .drawer__body {
  flex: 1;
}
.child__bar {
  justify-content: space-between;
  align-items: center;
  gap: var(--spacing-300);
  display: flex;
}
.child__count {
  font-size: 0.9375rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.revs {
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
}
.rev {
  column-gap: var(--spacing-250);
  padding-bottom: var(--spacing-400);
  grid-template-columns: 16px 1fr;
  display: grid;
  position: relative;
}
.rev:not(:last-child):before {
  content: "";
  background: var(--color-border-default);
  width: 2px;
  position: absolute;
  top: 20px;
  bottom: 2px;
  left: 7px;
}
.rev__dot {
  border-radius: var(--radius-full);
  z-index: 1;
  background: var(--color-background-elevation-raised);
  border: 2px solid var(--color-border-default-strong);
  width: 16px;
  height: 16px;
  margin-top: 2px;
}
.rev[data-kind="scheduled"] .rev__dot {
  border-color: var(--st-survey-scheduled);
}
.rev__main {
  gap: var(--spacing-150);
  flex-direction: column;
  min-width: 0;
  display: flex;
}
.rev__head {
  align-items: baseline;
  gap: var(--spacing-200);
  font-size: 1rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  flex-wrap: wrap;
  margin: 0;
  display: flex;
}
.rev__when {
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-secondary);
}
.rev__chiprow {
  align-items: center;
  gap: var(--spacing-200);
  flex-wrap: wrap;
  display: flex;
}
.rev__note {
  color: var(--color-content-default-secondary);
  margin: 0;
  font-size: 0.9375rem;
  line-height: 1.55;
}
.rev:last-child {
  padding-bottom: 0;
}
.rev[data-kind="blocked"] .rev__dot {
  background: var(--st-blocked);
  border-color: var(--st-blocked);
}
.rev__until {
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-secondary);
}
.rev__current {
  padding: 1px var(--spacing-200);
  border-radius: var(--radius-full);
  background: color-mix(in srgb, var(--color-background-brand) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--color-background-brand) 30%, transparent);
  font-size: 0.75rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-background-brand);
  white-space: nowrap;
  align-items: center;
  display: inline-flex;
}
.model-note {
  max-width: 86ch;
  padding: var(--spacing-400) var(--spacing-500);
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-300);
  gap: var(--spacing-200);
  flex-direction: column;
  display: flex;
}
.model-note__title {
  font-size: 1rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
}
.model-note__text {
  color: var(--color-content-default-secondary);
  margin: 0;
  font-size: 0.9375rem;
  line-height: 1.6;
}
.model-note__text code {
  font-family: var(--typography-font-family-mono);
  border-radius: var(--radius-100);
  background: var(--color-background-default);
  border: 1px solid var(--color-border-default-subtle);
  padding: 1px 5px;
  font-size: 0.875em;
}
.model-note__text strong {
  color: var(--color-content-default);
  font-weight: var(--typography-font-weight-semibold);
}
.evaluate {
  max-width: 86ch;
  padding: var(--spacing-500);
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-300);
  gap: var(--spacing-300);
  flex-direction: column;
  display: flex;
}
.evaluate__title {
  font-size: 1.25rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
}
.evaluate__list {
  gap: var(--spacing-250);
  flex-direction: column;
  margin: 0;
  padding-left: 1.5rem;
  display: flex;
}
.evaluate__list li {
  color: var(--color-content-default-secondary);
  font-size: 1rem;
  line-height: 1.55;
}
.round1 {
  gap: var(--spacing-500);
  padding-top: var(--spacing-600);
  border-top: 1px solid var(--color-border-default);
  flex-direction: column;
  display: flex;
}
.round1__head {
  gap: var(--spacing-200);
  flex-direction: column;
  display: flex;
}
.round1__title {
  font-size: 1.5rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
}
.round1__line {
  max-width: 86ch;
  color: var(--color-content-default-secondary);
  margin: 0;
  font-size: 1rem;
  line-height: 1.55;
}
.concepts {
  gap: var(--spacing-700) var(--spacing-500);
  grid-template-columns: repeat(auto-fit, minmax(360px, 1fr));
  align-items: start;
  display: grid;
}
.concept {
  gap: var(--spacing-400);
  flex-direction: column;
  justify-self: center;
  width: 100%;
  max-width: 460px;
  display: flex;
}
.concept__thesis {
  gap: var(--spacing-250);
  flex-direction: column;
  display: flex;
}
.concept__name {
  align-items: center;
  gap: var(--spacing-250);
  font-size: 1.25rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
  display: flex;
}
.concept__num {
  border-radius: var(--radius-full);
  background: var(--color-background-brand);
  color: #fff;
  width: 28px;
  height: 28px;
  font-size: 1rem;
  font-weight: var(--typography-font-weight-semibold);
  flex-shrink: 0;
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.concept__line {
  color: var(--color-content-default-secondary);
  margin: 0;
  font-size: 1rem;
  line-height: 1.5;
}
.concept__pt {
  gap: var(--spacing-100);
  flex-direction: column;
  display: flex;
}
.concept__pt-label {
  margin: var(--spacing-150) 0 0;
  font-size: 0.9375rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.concept__pt ul {
  gap: var(--spacing-100);
  flex-direction: column;
  margin: 0;
  padding-left: 1.25rem;
  display: flex;
}
.concept__pt li {
  color: var(--color-content-default-secondary);
  font-size: 0.9375rem;
  line-height: 1.5;
}
.action {
  gap: var(--spacing-250);
  padding: var(--spacing-400);
  border-radius: var(--radius-300);
  background: var(--color-background-default);
  border: 1px solid var(--color-border-default);
  flex-direction: column;
  display: flex;
}
.action--provisional {
  background: color-mix(in srgb, var(--st-provisional-block) 6%, transparent);
  border: 1px solid color-mix(in srgb, var(--st-provisional-block) 45%, transparent);
}
.action__title {
  font-size: 1.0625rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
}
.action--provisional .action__title {
  color: color-mix(in srgb, var(--st-provisional-block) 72%, #1a1a1a);
}
.action__text {
  color: var(--color-content-default-secondary);
  margin: 0;
  font-size: 0.9375rem;
  line-height: 1.55;
}
.action__facts {
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-secondary);
  margin: 0;
}
.action__btns {
  gap: var(--spacing-200);
  margin-top: var(--spacing-100);
  display: flex;
}
.rows {
  gap: var(--spacing-200);
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
}
.conflict {
  justify-content: space-between;
  align-items: center;
  gap: var(--spacing-300);
  padding: var(--spacing-250) var(--spacing-300);
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-300);
  display: flex;
}
.conflict__main {
  min-width: 0;
  font-size: 0.9375rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  flex-direction: column;
  flex: 1;
  gap: 2px;
  display: flex;
}
.conflict__sub {
  font-size: 0.8125rem;
  font-weight: var(--typography-font-weight-regular);
  color: var(--color-content-default-tertiary);
}
.conflict__meta {
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  white-space: nowrap;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  display: flex;
}
.action__conflict {
  align-items: flex-start;
  gap: var(--spacing-150);
  font-size: 0.9375rem;
  font-weight: var(--typography-font-weight-semibold);
  color: color-mix(in srgb, var(--st-blocked) 72%, #1a1a1a);
  margin: 0;
  line-height: 1.45;
  display: flex;
}
.action__conflict .esa-icon {
  flex-shrink: 0;
  margin-top: 2px;
}
.strip {
  align-items: center;
  gap: var(--spacing-250);
  padding: var(--spacing-250) var(--spacing-300);
  background: var(--color-background-default);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
  display: flex;
}
.strip .esa-icon {
  color: color-mix(in srgb, var(--st-blocked) 72%, #1a1a1a);
  flex-shrink: 0;
}
.strip__text {
  color: var(--color-content-default-secondary);
  font-size: 0.875rem;
  line-height: 1.45;
}
.strip__text strong {
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.disc-tabs {
  gap: var(--spacing-150);
  grid-template-columns: repeat(4, 1fr);
  display: grid;
}
.disc-tabs [role="tab"] {
  align-items: center;
  gap: var(--spacing-100);
  padding: var(--spacing-200) var(--spacing-100);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
  background: var(--color-background-elevation-raised);
  cursor: pointer;
  flex-direction: column;
  font-family: inherit;
  transition:
    border-color 0.12s,
    background 0.12s;
  display: flex;
}
.disc-tabs__dot {
  border-radius: var(--radius-full);
  flex-shrink: 0;
  width: 10px;
  height: 10px;
}
.disc-tabs__label {
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default);
}
.disc-tabs__dot[data-none="true"] {
  background: var(--color-background-elevation-raised);
  border: 1px dashed var(--color-border-default-strong);
}
.disc-tabs [role="tab"][aria-selected="true"] {
  border-color: var(--color-background-brand);
  background: var(--color-background-brand-subtle);
  box-shadow: inset 0 0 0 1px var(--color-background-brand);
}
.disc-panel {
  gap: var(--spacing-300);
  padding: var(--spacing-400);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-300);
  background: var(--color-background-elevation-raised);
  flex-direction: column;
  display: flex;
}
.disc-panel[hidden] {
  display: none;
}
.disc-panel__head {
  align-items: center;
  gap: var(--spacing-300);
  display: flex;
}
.disc-panel__when {
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-secondary);
}
.kv-text {
  color: var(--color-content-default-secondary);
  font-size: 0.9375rem;
  line-height: 1.5;
}
.disc-panel__warn {
  align-items: flex-start;
  gap: var(--spacing-150);
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-semibold);
  color: color-mix(in srgb, var(--st-blocked) 72%, #1a1a1a);
  margin: 0;
  line-height: 1.45;
  display: flex;
}
.disc-panel__warn .esa-icon {
  flex-shrink: 0;
  margin-top: 1px;
}
.disc-panel__foot {
  gap: var(--spacing-200);
  margin-top: var(--spacing-100);
  display: flex;
}
.steps {
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
}
.step {
  column-gap: var(--spacing-300);
  padding-bottom: var(--spacing-400);
  grid-template-columns: 24px 1fr;
  display: grid;
  position: relative;
}
.step:not(:last-child):before {
  content: "";
  background: var(--color-border-default);
  width: 2px;
  position: absolute;
  top: 28px;
  bottom: 4px;
  left: 11px;
}
.step__dot {
  border-radius: var(--radius-full);
  background: var(--color-background-elevation-raised);
  border: 2px solid var(--color-border-default-strong);
  z-index: 1;
  justify-content: center;
  align-items: center;
  width: 24px;
  height: 24px;
  margin-top: 0;
  display: flex;
}
.step[data-state="done"] .step__dot {
  background: var(--color-background-brand);
  border-color: var(--color-background-brand);
}
.step[data-state="done"] .step__dot:after {
  content: "";
  border-bottom: 2px solid #fff;
  border-left: 2px solid #fff;
  width: 9px;
  height: 5px;
  margin-top: -2px;
  transform: rotate(-45deg);
}
.step__content {
  gap: var(--spacing-150);
  flex-direction: column;
  min-width: 0;
  padding-top: 2px;
  display: flex;
}
.step__title {
  align-items: baseline;
  gap: var(--spacing-200);
  font-size: 1rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  flex-wrap: wrap;
  margin: 0;
  display: flex;
}
.step__when {
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-secondary);
}
.step__text {
  color: var(--color-content-default-secondary);
  margin: 0;
  font-size: 0.9375rem;
  line-height: 1.5;
}
.step[data-state="scheduled"] .step__dot {
  border-color: var(--st-survey-scheduled);
}
.step[data-state="live-red"] .step__dot {
  border-color: var(--st-provisional-block);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--st-provisional-block) 18%, transparent);
}
.step[data-state="live-red"] .step__dot:after {
  content: "";
  border-radius: var(--radius-full);
  background: var(--st-provisional-block);
  width: 8px;
  height: 8px;
}
.step[data-state="live-red"] .step__when {
  color: color-mix(in srgb, var(--st-provisional-block) 72%, #1a1a1a);
}
.check {
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
}
.check__row {
  column-gap: var(--spacing-250);
  padding: var(--spacing-200) 0;
  grid-template-columns: 12px 1fr auto;
  align-items: center;
  row-gap: 2px;
  display: grid;
}
.check__dot {
  border-radius: var(--radius-full);
  justify-self: center;
  width: 10px;
  height: 10px;
}
.check__dim {
  font-size: 0.9375rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.check__state {
  color: var(--color-content-default-secondary);
  grid-column: 2/-1;
  font-size: 0.875rem;
}
.check__row + .check__row {
  border-top: 1px solid var(--color-border-default-subtle);
}
.check__dot[data-none="true"] {
  background: var(--color-background-elevation-raised);
  border: 1px dashed var(--color-border-default-strong);
}
.action--instep {
  padding: var(--spacing-300);
  margin-top: var(--spacing-250);
}
.action__text strong {
  color: color-mix(in srgb, var(--st-provisional-block) 72%, #1a1a1a);
  font-weight: var(--typography-font-weight-semibold);
}
.step[data-state="future"] .step__dot {
  border-style: dashed;
  border-color: var(--color-border-default-strong);
}
.step:last-child {
  padding-bottom: 0;
}
.step__flag {
  align-items: flex-start;
  gap: var(--spacing-150);
  font-size: 0.9375rem;
  font-weight: var(--typography-font-weight-semibold);
  color: color-mix(in srgb, var(--st-blocked) 72%, #1a1a1a);
  margin: 0;
  line-height: 1.45;
  display: flex;
}
.step__flag .esa-icon {
  flex-shrink: 0;
  margin-top: 2px;
}
.step__act {
  gap: var(--spacing-200);
  margin-top: var(--spacing-100);
  display: flex;
}
.survey__link {
  font-size: 0.9375rem;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-background-brand-muted);
  cursor: pointer;
  text-decoration: none;
}
.step[data-state="live"] .step__dot {
  border-color: var(--st-survey-scheduled);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--st-survey-scheduled) 22%, transparent);
}
.step[data-state="live"] .step__dot:after {
  content: "";
  border-radius: var(--radius-full);
  background: var(--st-survey-scheduled);
  width: 8px;
  height: 8px;
}
.check__act {
  grid-area: 1/3;
}
.esa-icon {
  --_icon-size: var(--icon-size-md, 20px);
  width: var(--_icon-size);
  height: var(--_icon-size);
  color: inherit;
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.esa-icon--sm {
  --_icon-size: var(--icon-size-sm, 16px);
}
.esa-icon svg {
  width: var(--_icon-size);
  height: var(--_icon-size);
  display: block;
}

full.css:
:root,
[data-theme="beacon"] {
  --badge-bg: #43608a;
  --badge-text-color: #fcfcfc;
  --border-width-default: 1px;
  --button-radius-md: 0.25rem;
  --button-radius-sm: 0.25rem;
  --color-background-brand-muted: #eef5f4;
  --color-background-default: #fafafa;
  --color-background-elevation-raised: #fcfcfc;
  --color-background-utility-danger: #ce2c31;
  --color-background-utility-danger-hover: #641723;
  --color-border-default: #dcdcdc;
  --color-border-default-strong: #bdbdbd;
  --color-border-default-subtle: #efefef;
  --color-content-default: #3d3d3d;
  --color-content-default-knockout: #fcfcfc;
  --color-content-default-secondary: #525252;
  --color-content-default-tertiary: #656565;
  --color-content-on-brand-muted: #203c25;
  --color-content-utility-danger: #ce2c31;
  --font-decorative: "Besley", serif;
  --font-size-100: clamp(0.625rem, 0.56rem + 0.32vw, 0.75rem);
  --font-size-200: clamp(0.75rem, 0.66rem + 0.44vw, 0.9375rem);
  --font-size-400: clamp(1rem, 0.88rem + 0.6vw, 1.25rem);
  --form-label-color: #525252;
  --icon-size-md: 20px;
  --icon-size-sm: 16px;
  --radius-100: 0.25rem;
  --radius-200: 0.5rem;
  --radius-300: 0.5rem;
  --radius-chip: 0.25rem;
  --radius-full: 9999px;
  --radius-md: 0.25rem;
  --radius-sm: 0.25rem;
  --spacing-100: 0.25rem;
  --spacing-150: 0.375rem;
  --spacing-200: 0.5rem;
  --spacing-250: 0.625rem;
  --spacing-300: 0.75rem;
  --spacing-400: 1rem;
  --spacing-500: 1.5rem;
  --spacing-600: 2rem;
  --spacing-700: 3rem;
  --spacing-800: 4rem;
  --st-blocked: #d73027;
  --st-provisional-block: #d73027;
  --st-survey-scheduled: #74add1;
  --transition-fast: 0.15s ease;
  --typography-body-md-font-family: "DM Sans", sans-serif;
  --typography-body-md-font-size: clamp(0.75rem, 0.66rem + 0.44vw, 0.9375rem);
  --typography-body-md-font-weight: 350;
  --typography-body-md-letter-spacing: 0.01em;
  --typography-body-md-line-height: 1.6;
  --typography-font-family-mono: "Roboto Mono", ui-monospace, monospace;
  --typography-font-family-sans: "DM Sans", sans-serif;
  --typography-font-weight-medium: 500;
  --typography-font-weight-regular: 350;
  --typography-font-weight-semibold: 550;
  --typography-label-md-font-size: clamp(0.75rem, 0.66rem + 0.44vw, 0.9375rem);
  --typography-label-sm-strong-font-family: "DM Sans", sans-serif;
  --typography-label-sm-strong-font-size: clamp(0.6875rem, 0.61rem + 0.38vw, 0.875rem);
  --typography-label-sm-strong-font-weight: 550;
  --typography-label-sm-strong-letter-spacing: 0.01em;
  --typography-label-sm-strong-line-height: 1.6;
  --typography-microcopy-md-font-family: "DM Sans", sans-serif;
  --typography-microcopy-md-font-size: clamp(0.75rem, 0.66rem + 0.44vw, 0.9375rem);
  --typography-microcopy-md-font-weight: 500;
  --typography-microcopy-md-letter-spacing: 0.01em;
  --typography-microcopy-md-line-height: 1;
  --typography-microcopy-xs-font-family: "DM Sans", sans-serif;
  --typography-microcopy-xs-font-size: clamp(0.625rem, 0.56rem + 0.32vw, 0.75rem);
  --typography-microcopy-xs-font-weight: 500;
  --typography-microcopy-xs-letter-spacing: 0.01em;
  --typography-microcopy-xs-line-height: 1;
  --typography-microcopy-xs-strong-font-family: "DM Sans", sans-serif;
  --typography-microcopy-xs-strong-font-size: clamp(0.625rem, 0.56rem + 0.32vw, 0.75rem);
  --typography-microcopy-xs-strong-font-weight: 550;
  --typography-microcopy-xs-strong-letter-spacing: 0.01em;
  --typography-microcopy-xs-strong-line-height: 1;
}

*,
:before,
:after {
  box-sizing: border-box;
}
body {
  font-family: var(--typography-font-family-sans, system-ui, sans-serif);
  font-weight: var(--typography-font-weight-regular, 350);
  color: var(--color-content-default, #3d3d3d);
  background: var(--color-background-elevation-raised, #fff);
  -webkit-font-smoothing: antialiased;
  margin: 0;
}
:where(h1, h2, h3, h4, h5, h6, p, figure, blockquote, dl, dd, ul, ol, pre) {
  margin: 0;
}
button {
  cursor: pointer;
  background: 0 0;
  border: 0;
  font-family: inherit;
}
.stack {
  --gap: var(--spacing-400, 1rem);
  gap: var(--gap);
  flex-direction: column;
  display: flex;
}
a {
  color: var(--color-content-link, #005862);
  text-decoration: none;
}
.typography-microcopy-xs {
  font-family: var(--typography-microcopy-xs-font-family);
  font-size: var(--typography-microcopy-xs-font-size);
  font-weight: var(--typography-microcopy-xs-font-weight);
  line-height: var(--typography-microcopy-xs-line-height);
  letter-spacing: var(--typography-microcopy-xs-letter-spacing);
}
.typography-label-sm-strong {
  font-family: var(--typography-label-sm-strong-font-family);
  font-size: var(--typography-label-sm-strong-font-size);
  font-weight: var(--typography-label-sm-strong-font-weight);
  line-height: var(--typography-label-sm-strong-line-height);
  letter-spacing: var(--typography-label-sm-strong-letter-spacing);
}
.typography-microcopy-md {
  font-family: var(--typography-microcopy-md-font-family);
  font-size: var(--typography-microcopy-md-font-size);
  font-weight: var(--typography-microcopy-md-font-weight);
  line-height: var(--typography-microcopy-md-line-height);
  letter-spacing: var(--typography-microcopy-md-letter-spacing);
}
.typography-microcopy-xs-strong {
  font-family: var(--typography-microcopy-xs-strong-font-family);
  font-size: var(--typography-microcopy-xs-strong-font-size);
  font-weight: var(--typography-microcopy-xs-strong-font-weight);
  line-height: var(--typography-microcopy-xs-strong-line-height);
  letter-spacing: var(--typography-microcopy-xs-strong-letter-spacing);
}
.typography-body-md {
  font-family: var(--typography-body-md-font-family);
  font-size: var(--typography-body-md-font-size);
  font-weight: var(--typography-body-md-font-weight);
  line-height: var(--typography-body-md-line-height);
  letter-spacing: var(--typography-body-md-letter-spacing);
}
.esa-button {
  --_btn-pad-y: var(--spacing-300, 0.75rem);
  --_btn-padding-x: var(--spacing-300, 0.75rem);
  --_btn-radius: var(--button-radius-md, 0.5rem);
  --_accent: var(--color-background-brand, #46a758);
  --_accent-hover: var(--color-background-brand-hover, #3e9b4f);
  --_on: var(--color-content-default-knockout, #fcfcfc);
  --_accent-text: var(--_accent);
  --_btn-tint-hover: color-mix(in srgb, var(--_accent) 8%, transparent);
  --_btn-tint-active: color-mix(in srgb, var(--_accent) 14%, transparent);
  display: inline-block;
}
.esa-button--sm {
  --_btn-pad-y: var(--spacing-250, 0.625rem);
  --_btn-padding-x: var(--spacing-250, 0.625rem);
  --_btn-radius: var(--button-radius-sm, 4px);
}
.esa-button--variant-danger {
  --_accent: var(--color-background-utility-danger);
  --_accent-hover: var(--color-background-utility-danger-hover);
  --_accent-text: var(--color-content-utility-danger);
}
.esa-button__native {
  justify-content: center;
  align-items: center;
  gap: var(--spacing-200, 8px);
  width: 100%;
  padding-block: var(--_btn-pad-y);
  padding-inline: var(--_btn-padding-x);
  border: var(--border-width-default, 1px) solid transparent;
  border-radius: var(--_btn-radius);
  cursor: pointer;
  transition:
    background var(--transition-fast, 0.15s ease),
    border-color var(--transition-fast, 0.15s ease);
  -webkit-appearance: none;
  appearance: none;
  text-decoration: none;
  display: inline-flex;
}
.esa-button--appearance-fill .esa-button__native {
  background: var(--_accent);
  color: var(--_on);
  border-color: var(--_accent-border, transparent);
}
.esa-button__label {
  white-space: nowrap;
}
.esa-button--appearance-outline .esa-button__native,
.esa-button--appearance-dashed .esa-button__native {
  color: var(--_accent-text);
  border-color: var(--_accent);
  background: 0 0;
}
.esa-button--variant-ghost .esa-button__native {
  color: var(--color-content-default, #202020);
  background: 0 0;
  border-color: #0000;
}
.esa-button--variant-ghost.esa-button--appearance-outline .esa-button__native,
.esa-button--variant-ghost.esa-button--appearance-dashed .esa-button__native {
  border-color: var(--color-border-default, #cecece);
}
.esa-button--variant-chrome .esa-button__native {
  color: inherit;
  background: 0 0;
  border-color: #0000;
}
.esa-button--icon-only .esa-button__native {
  padding-inline: var(--_btn-pad-y);
  aspect-ratio: 1;
}
.esa-button--variant-primary {
  --_accent-text: var(--color-content-brand);
}
.bcn-status-chip {
  align-items: center;
  gap: var(--spacing-150);
  padding: 2px var(--spacing-250);
  border-radius: var(--radius-full);
  font-size: var(--font-size-100);
  font-weight: var(--typography-font-weight-semibold);
  white-space: nowrap;
  background: color-mix(in srgb, var(--_chip) 16%, transparent);
  color: color-mix(in srgb, var(--_chip) 72%, #1a1a1a);
  display: inline-flex;
}
.bcn-status-chip__dot {
  border-radius: var(--radius-full);
  background: var(--_chip);
  flex-shrink: 0;
  width: 8px;
  height: 8px;
}
.bcn-key-value {
  flex-direction: column;
  gap: 2px;
  display: flex;
}
.bcn-key-value__key {
  font-size: var(--typography-label-md-font-size);
  font-weight: var(--typography-font-weight-medium);
  color: var(--form-label-color);
}
.bcn-key-value__val {
  font-size: var(--typography-label-md-font-size);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.esa-collapsible {
  border: var(--border-width-default, 1px) solid var(--color-border-default, #cecece);
  border-radius: var(--radius-md, 0.5rem);
  background: var(--color-background-elevation-raised, #fcfcfc);
}
.esa-collapsible--flush {
  background: 0 0;
  border: none;
  border-radius: 0;
}
.esa-collapsible__summary {
  align-items: center;
  gap: var(--spacing-200, 0.5rem);
  padding: var(--spacing-300, 0.75rem) var(--spacing-400, 1rem);
  color: var(--color-content-default, #202020);
  cursor: pointer;
  list-style: none;
  display: flex;
}
.esa-collapsible--flush > .esa-collapsible__summary,
.esa-collapsible--flush > .esa-collapsible__body {
  padding-inline: 0;
}
.esa-collapsible__summary .esa-icon {
  color: var(--color-content-default-secondary, #646464);
  flex-shrink: 0;
}
.esa-collapsible__summary:after {
  content: "";
  border-right: 2px solid var(--color-content-default-secondary, #646464);
  border-bottom: 2px solid var(--color-content-default-secondary, #646464);
  width: 8px;
  height: 8px;
  margin-left: auto;
  transition: transform 0.15s;
  transform: rotate(-45deg);
}
.esa-badge {
  --_badge-bg: var(--badge-bg, var(--color-background-brand, #46a758));
  --_badge-text: var(--badge-text-color, var(--color-content-default-knockout, #fcfcfc));
  --_badge-padding-y: var(--spacing-150, 0.375rem);
  --_badge-padding-x: var(--spacing-200, 0.5rem);
  min-width: calc(1lh + 2 * var(--_badge-padding-y));
  padding-block: var(--_badge-padding-y);
  padding-inline: var(--_badge-padding-x);
  border-radius: var(--radius-chip, var(--radius-sm, 0.25rem));
  background: var(--_badge-bg);
  color: var(--_badge-text);
  white-space: nowrap;
  box-sizing: border-box;
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.esa-badge--sm {
  --_badge-padding-y: var(--spacing-100, 0.25rem);
  --_badge-padding-x: var(--spacing-150, 0.375rem);
}
.esa-badge--secondary {
  --_badge-bg: var(--color-background-brand-muted, #e9f6e9);
  --_badge-text: var(--color-content-on-brand-muted, #203c25);
}
.esa-collapsible[open] > .esa-collapsible__summary:after {
  transform: rotate(45deg);
}
.esa-collapsible__body {
  gap: var(--spacing-400, 1rem);
  padding: 0 var(--spacing-400, 1rem) var(--spacing-400, 1rem);
  flex-direction: column;
  display: flex;
}
body {
  background: var(--color-background-default);
}
.spec {
  max-width: 1480px;
  padding: var(--spacing-700) var(--spacing-500) var(--spacing-800);
  gap: var(--spacing-700);
  flex-direction: column;
  margin: 0 auto;
  display: flex;
}
.spec__head {
  gap: var(--spacing-300);
  flex-direction: column;
  display: flex;
}
.spec__title {
  font-family: var(--font-decorative);
  font-size: 2rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
}
.spec__intro {
  max-width: 86ch;
  font-size: var(--font-size-200, 1rem);
  color: var(--color-content-default-secondary);
  margin: 0;
  line-height: 1.6;
}
.spec__intro strong {
  color: var(--color-content-default);
  font-weight: var(--typography-font-weight-semibold);
}
.v2 {
  gap: var(--spacing-500);
  flex-direction: column;
  display: flex;
}
.v2__head {
  gap: var(--spacing-300);
  flex-direction: column;
  display: flex;
}
.v2__title {
  font-size: 1.5rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
}
.v2__changes {
  gap: var(--spacing-200);
  flex-direction: column;
  max-width: 86ch;
  margin: 0;
  padding-left: 1.25rem;
  display: flex;
}
.v2__changes li {
  color: var(--color-content-default-secondary);
  font-size: 1rem;
  line-height: 1.55;
}
.v2__changes strong {
  color: var(--color-content-default);
  font-weight: var(--typography-font-weight-semibold);
}
.v2__pair {
  gap: var(--spacing-500);
  grid-template-columns: repeat(auto-fit, minmax(360px, 1fr));
  align-items: start;
  max-width: 1000px;
  display: grid;
}
.mockup {
  gap: var(--spacing-200);
  flex-direction: column;
  margin: 0;
  display: flex;
}
.v2__pair .mockup {
  justify-self: center;
  width: 100%;
  max-width: 460px;
}
.mockup__case {
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default-secondary);
  line-height: 1.5;
}
.drawer {
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-300);
  overflow: hidden;
  box-shadow: 0 12px 32px #0000001a;
}
.drawer__head {
  padding: var(--spacing-400);
  border-bottom: 1px solid var(--color-border-default);
  flex-direction: column;
  gap: 2px;
  display: flex;
}
.drawer__headrow {
  align-items: center;
  gap: var(--spacing-300);
  display: flex;
}
.drawer__title {
  font-size: var(--font-size-400);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
}
.bcn-status-chip[data-status="provisional-block"],
.bcn-status-chip[data-status="provisional-block"] .bcn-status-chip__dot {
  background: var(--color-background-elevation-raised);
  box-shadow: inset 0 0 0 1.5px var(--st-provisional-block);
}
.drawer__sub {
  color: var(--color-content-default-secondary);
  margin: 0;
  font-size: 0.875rem;
}
.band {
  gap: var(--spacing-200) var(--spacing-300);
  padding: var(--spacing-250) var(--spacing-400);
  background: var(--color-background-default);
  border-bottom: 1px solid var(--color-border-default);
  grid-template-columns: repeat(3, 1fr);
  display: grid;
}
.drawer__body {
  gap: var(--spacing-400);
  padding: var(--spacing-400);
  flex-direction: column;
  display: flex;
}
.decide {
  gap: var(--spacing-200);
  padding: var(--spacing-250) var(--spacing-300);
  border-radius: var(--radius-200);
  background: var(--color-background-default);
  border: 1px solid var(--color-border-default);
  flex-direction: column;
  display: flex;
}
.decide--prov {
  background: color-mix(in srgb, var(--st-provisional-block) 6%, transparent);
  border-color: color-mix(in srgb, var(--st-provisional-block) 45%, transparent);
  --color-background-utility-danger: var(--st-provisional-block);
}
.decide__line {
  font-size: 0.9375rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
  line-height: 1.45;
}
.decide__line--fact {
  align-items: center;
  gap: var(--spacing-250);
  flex-wrap: wrap;
  display: flex;
}
.decide--prov .decide__line {
  color: color-mix(in srgb, var(--st-provisional-block) 72%, #1a1a1a);
}
.obs-id {
  font-family: var(--typography-font-family-mono);
  padding: 1px var(--spacing-200);
  border-radius: var(--radius-100);
  background: var(--color-background-elevation-raised);
  border: 1px solid color-mix(in srgb, var(--st-provisional-block) 45%, transparent);
  color: color-mix(in srgb, var(--st-provisional-block) 72%, #1a1a1a);
  white-space: nowrap;
  flex-shrink: 0;
  font-size: 0.8125rem;
  font-weight: 500;
}
.decide__actions {
  justify-content: flex-end;
  gap: var(--spacing-200);
  display: flex;
}
.drawer__section {
  align-items: center;
  gap: var(--spacing-200);
  margin: 0 0 var(--spacing-300);
  font-size: 0.9375rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  display: flex;
}
.drawer__section .esa-icon {
  color: var(--color-content-default-secondary);
  flex-shrink: 0;
}
.board {
  gap: var(--spacing-200);
  grid-template-columns: 1fr 1fr;
  display: grid;
}
.board__cell--btn {
  cursor: pointer;
  text-align: left;
  border: 1px solid var(--color-border-default-subtle);
  background: var(--color-background-elevation-raised);
  width: 100%;
  font-family: inherit;
  transition:
    border-color 0.12s,
    background 0.12s;
}
.board__cell {
  align-items: flex-start;
  gap: var(--spacing-150);
  padding: var(--spacing-250) var(--spacing-300);
  border: 1px solid var(--color-border-default-subtle);
  border-radius: var(--radius-200);
  background: var(--color-background-elevation-raised);
  flex-direction: column;
  display: flex;
}
.board__cellhead {
  align-items: center;
  gap: var(--spacing-150);
  width: 100%;
  display: flex;
}
.board__dim {
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.board__cellhead .board__dim {
  flex: 1;
  min-width: 0;
}
.board__chev {
  color: var(--color-content-default-tertiary);
  display: inline-flex;
}
.board__meta {
  color: var(--color-content-default-tertiary);
  font-size: 0.8125rem;
}
.unreviewed {
  padding: 2px var(--spacing-250);
  border: 1px dashed var(--color-border-default-strong);
  border-radius: var(--radius-full);
  font-size: var(--font-size-100);
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-tertiary);
  white-space: nowrap;
  align-items: center;
  display: inline-flex;
}
.drawer__more {
  flex-direction: column;
  display: flex;
}
.drawer__more .esa-collapsible + .esa-collapsible {
  border-top: 1px solid var(--color-border-default-subtle);
}
.drawer__foot {
  justify-content: flex-end;
  gap: var(--spacing-200);
  padding: var(--spacing-300) var(--spacing-400);
  border-top: 1px solid var(--color-border-default);
  background: var(--color-background-elevation-raised);
  display: flex;
}
.decide__row {
  align-items: center;
  gap: var(--spacing-250);
  display: flex;
}
.decide__row--warn .esa-icon {
  color: color-mix(in srgb, var(--st-blocked) 72%, #1a1a1a);
  flex-shrink: 0;
}
.decide__warntext {
  min-width: 0;
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-semibold);
  color: color-mix(in srgb, var(--st-blocked) 72%, #1a1a1a);
  flex: 1;
  line-height: 1.45;
}
.v2__sub {
  margin: var(--spacing-300) 0 0;
  font-size: 1.1875rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.stack {
  width: 100%;
  max-width: 540px;
  position: relative;
}
.stack__parent {
  width: calc(100% - 72px);
  position: relative;
}
.band--4 {
  grid-template-columns: repeat(4, 1fr);
}
.band__alert {
  font-size: var(--typography-label-md-font-size);
  font-weight: var(--typography-font-weight-semibold);
  color: color-mix(in srgb, var(--st-blocked) 72%, #1a1a1a);
}
.decide--blocked {
  background: color-mix(in srgb, var(--st-blocked) 10%, transparent);
  border-color: color-mix(in srgb, var(--st-blocked) 30%, transparent);
}
.decide--blocked .decide__line {
  color: color-mix(in srgb, var(--st-blocked) 72%, #1a1a1a);
}
.board__cell--btn[data-active] {
  border-color: var(--color-background-brand);
  box-shadow: inset 0 0 0 1px var(--color-background-brand);
  background: var(--color-background-brand-subtle);
}
.stack__parent:after {
  content: "";
  border-radius: var(--radius-300);
  z-index: 4;
  pointer-events: none;
  background: #0d111438;
  position: absolute;
  inset: 0;
}
.stack__child {
  z-index: 5;
  flex-direction: column;
  width: calc(100% - 72px);
  display: flex;
  position: absolute;
  top: 0;
  bottom: 0;
  right: 0;
  box-shadow: -16px 0 40px #00000038;
}
.drawer__close {
  color: var(--color-content-default-secondary);
  margin-left: auto;
}
.stack__child .drawer__body {
  flex: 1;
}
.child__bar {
  justify-content: space-between;
  align-items: center;
  gap: var(--spacing-300);
  display: flex;
}
.child__count {
  font-size: 0.9375rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.revs {
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
}
.rev {
  column-gap: var(--spacing-250);
  padding-bottom: var(--spacing-400);
  grid-template-columns: 16px 1fr;
  display: grid;
  position: relative;
}
.rev:not(:last-child):before {
  content: "";
  background: var(--color-border-default);
  width: 2px;
  position: absolute;
  top: 20px;
  bottom: 2px;
  left: 7px;
}
.rev__dot {
  border-radius: var(--radius-full);
  z-index: 1;
  background: var(--color-background-elevation-raised);
  border: 2px solid var(--color-border-default-strong);
  width: 16px;
  height: 16px;
  margin-top: 2px;
}
.rev[data-kind="scheduled"] .rev__dot {
  border-color: var(--st-survey-scheduled);
}
.rev__main {
  gap: var(--spacing-150);
  flex-direction: column;
  min-width: 0;
  display: flex;
}
.rev__head {
  align-items: baseline;
  gap: var(--spacing-200);
  font-size: 1rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  flex-wrap: wrap;
  margin: 0;
  display: flex;
}
.rev__when {
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-secondary);
}
.rev__chiprow {
  align-items: center;
  gap: var(--spacing-200);
  flex-wrap: wrap;
  display: flex;
}
.rev__note {
  color: var(--color-content-default-secondary);
  margin: 0;
  font-size: 0.9375rem;
  line-height: 1.55;
}
.rev:last-child {
  padding-bottom: 0;
}
.rev[data-kind="blocked"] .rev__dot {
  background: var(--st-blocked);
  border-color: var(--st-blocked);
}
.rev__until {
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-secondary);
}
.rev__current {
  padding: 1px var(--spacing-200);
  border-radius: var(--radius-full);
  background: color-mix(in srgb, var(--color-background-brand) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--color-background-brand) 30%, transparent);
  font-size: 0.75rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-background-brand);
  white-space: nowrap;
  align-items: center;
  display: inline-flex;
}
.model-note {
  max-width: 86ch;
  padding: var(--spacing-400) var(--spacing-500);
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-300);
  gap: var(--spacing-200);
  flex-direction: column;
  display: flex;
}
.model-note__title {
  font-size: 1rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
}
.model-note__text {
  color: var(--color-content-default-secondary);
  margin: 0;
  font-size: 0.9375rem;
  line-height: 1.6;
}
.model-note__text code {
  font-family: var(--typography-font-family-mono);
  border-radius: var(--radius-100);
  background: var(--color-background-default);
  border: 1px solid var(--color-border-default-subtle);
  padding: 1px 5px;
  font-size: 0.875em;
}
.model-note__text strong {
  color: var(--color-content-default);
  font-weight: var(--typography-font-weight-semibold);
}
.evaluate {
  max-width: 86ch;
  padding: var(--spacing-500);
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-300);
  gap: var(--spacing-300);
  flex-direction: column;
  display: flex;
}
.evaluate__title {
  font-size: 1.25rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
}
.evaluate__list {
  gap: var(--spacing-250);
  flex-direction: column;
  margin: 0;
  padding-left: 1.5rem;
  display: flex;
}
.evaluate__list li {
  color: var(--color-content-default-secondary);
  font-size: 1rem;
  line-height: 1.55;
}
.round1 {
  gap: var(--spacing-500);
  padding-top: var(--spacing-600);
  border-top: 1px solid var(--color-border-default);
  flex-direction: column;
  display: flex;
}
.round1__head {
  gap: var(--spacing-200);
  flex-direction: column;
  display: flex;
}
.round1__title {
  font-size: 1.5rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
}
.round1__line {
  max-width: 86ch;
  color: var(--color-content-default-secondary);
  margin: 0;
  font-size: 1rem;
  line-height: 1.55;
}
.concepts {
  gap: var(--spacing-700) var(--spacing-500);
  grid-template-columns: repeat(auto-fit, minmax(360px, 1fr));
  align-items: start;
  display: grid;
}
.concept {
  gap: var(--spacing-400);
  flex-direction: column;
  justify-self: center;
  width: 100%;
  max-width: 460px;
  display: flex;
}
.concept__thesis {
  gap: var(--spacing-250);
  flex-direction: column;
  display: flex;
}
.concept__name {
  align-items: center;
  gap: var(--spacing-250);
  font-size: 1.25rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
  display: flex;
}
.concept__num {
  border-radius: var(--radius-full);
  background: var(--color-background-brand);
  color: #fff;
  width: 28px;
  height: 28px;
  font-size: 1rem;
  font-weight: var(--typography-font-weight-semibold);
  flex-shrink: 0;
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.concept__line {
  color: var(--color-content-default-secondary);
  margin: 0;
  font-size: 1rem;
  line-height: 1.5;
}
.concept__pt {
  gap: var(--spacing-100);
  flex-direction: column;
  display: flex;
}
.concept__pt-label {
  margin: var(--spacing-150) 0 0;
  font-size: 0.9375rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.concept__pt ul {
  gap: var(--spacing-100);
  flex-direction: column;
  margin: 0;
  padding-left: 1.25rem;
  display: flex;
}
.concept__pt li {
  color: var(--color-content-default-secondary);
  font-size: 0.9375rem;
  line-height: 1.5;
}
.action {
  gap: var(--spacing-250);
  padding: var(--spacing-400);
  border-radius: var(--radius-300);
  background: var(--color-background-default);
  border: 1px solid var(--color-border-default);
  flex-direction: column;
  display: flex;
}
.action--provisional {
  background: color-mix(in srgb, var(--st-provisional-block) 6%, transparent);
  border: 1px solid color-mix(in srgb, var(--st-provisional-block) 45%, transparent);
}
.action__title {
  font-size: 1.0625rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
}
.action--provisional .action__title {
  color: color-mix(in srgb, var(--st-provisional-block) 72%, #1a1a1a);
}
.action__text {
  color: var(--color-content-default-secondary);
  margin: 0;
  font-size: 0.9375rem;
  line-height: 1.55;
}
.action__facts {
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-secondary);
  margin: 0;
}
.action__btns {
  gap: var(--spacing-200);
  margin-top: var(--spacing-100);
  display: flex;
}
.rows {
  gap: var(--spacing-200);
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
}
.conflict {
  justify-content: space-between;
  align-items: center;
  gap: var(--spacing-300);
  padding: var(--spacing-250) var(--spacing-300);
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-300);
  display: flex;
}
.conflict__main {
  min-width: 0;
  font-size: 0.9375rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  flex-direction: column;
  flex: 1;
  gap: 2px;
  display: flex;
}
.conflict__sub {
  font-size: 0.8125rem;
  font-weight: var(--typography-font-weight-regular);
  color: var(--color-content-default-tertiary);
}
.conflict__meta {
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  white-space: nowrap;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  display: flex;
}
.action__conflict {
  align-items: flex-start;
  gap: var(--spacing-150);
  font-size: 0.9375rem;
  font-weight: var(--typography-font-weight-semibold);
  color: color-mix(in srgb, var(--st-blocked) 72%, #1a1a1a);
  margin: 0;
  line-height: 1.45;
  display: flex;
}
.action__conflict .esa-icon {
  flex-shrink: 0;
  margin-top: 2px;
}
.strip {
  align-items: center;
  gap: var(--spacing-250);
  padding: var(--spacing-250) var(--spacing-300);
  background: var(--color-background-default);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
  display: flex;
}
.strip .esa-icon {
  color: color-mix(in srgb, var(--st-blocked) 72%, #1a1a1a);
  flex-shrink: 0;
}
.strip__text {
  color: var(--color-content-default-secondary);
  font-size: 0.875rem;
  line-height: 1.45;
}
.strip__text strong {
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.disc-tabs {
  gap: var(--spacing-150);
  grid-template-columns: repeat(4, 1fr);
  display: grid;
}
.disc-tabs [role="tab"] {
  align-items: center;
  gap: var(--spacing-100);
  padding: var(--spacing-200) var(--spacing-100);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
  background: var(--color-background-elevation-raised);
  cursor: pointer;
  flex-direction: column;
  font-family: inherit;
  transition:
    border-color 0.12s,
    background 0.12s;
  display: flex;
}
.disc-tabs__dot {
  border-radius: var(--radius-full);
  flex-shrink: 0;
  width: 10px;
  height: 10px;
}
.disc-tabs__label {
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default);
}
.disc-tabs__dot[data-none="true"] {
  background: var(--color-background-elevation-raised);
  border: 1px dashed var(--color-border-default-strong);
}
.disc-tabs [role="tab"][aria-selected="true"] {
  border-color: var(--color-background-brand);
  background: var(--color-background-brand-subtle);
  box-shadow: inset 0 0 0 1px var(--color-background-brand);
}
.disc-panel {
  gap: var(--spacing-300);
  padding: var(--spacing-400);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-300);
  background: var(--color-background-elevation-raised);
  flex-direction: column;
  display: flex;
}
.disc-panel[hidden] {
  display: none;
}
.disc-panel__head {
  align-items: center;
  gap: var(--spacing-300);
  display: flex;
}
.disc-panel__when {
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-secondary);
}
.kv-text {
  color: var(--color-content-default-secondary);
  font-size: 0.9375rem;
  line-height: 1.5;
}
.disc-panel__warn {
  align-items: flex-start;
  gap: var(--spacing-150);
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-semibold);
  color: color-mix(in srgb, var(--st-blocked) 72%, #1a1a1a);
  margin: 0;
  line-height: 1.45;
  display: flex;
}
.disc-panel__warn .esa-icon {
  flex-shrink: 0;
  margin-top: 1px;
}
.disc-panel__foot {
  gap: var(--spacing-200);
  margin-top: var(--spacing-100);
  display: flex;
}
.steps {
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
}
.step {
  column-gap: var(--spacing-300);
  padding-bottom: var(--spacing-400);
  grid-template-columns: 24px 1fr;
  display: grid;
  position: relative;
}
.step:not(:last-child):before {
  content: "";
  background: var(--color-border-default);
  width: 2px;
  position: absolute;
  top: 28px;
  bottom: 4px;
  left: 11px;
}
.step__dot {
  border-radius: var(--radius-full);
  background: var(--color-background-elevation-raised);
  border: 2px solid var(--color-border-default-strong);
  z-index: 1;
  justify-content: center;
  align-items: center;
  width: 24px;
  height: 24px;
  margin-top: 0;
  display: flex;
}
.step[data-state="done"] .step__dot {
  background: var(--color-background-brand);
  border-color: var(--color-background-brand);
}
.step[data-state="done"] .step__dot:after {
  content: "";
  border-bottom: 2px solid #fff;
  border-left: 2px solid #fff;
  width: 9px;
  height: 5px;
  margin-top: -2px;
  transform: rotate(-45deg);
}
.step__content {
  gap: var(--spacing-150);
  flex-direction: column;
  min-width: 0;
  padding-top: 2px;
  display: flex;
}
.step__title {
  align-items: baseline;
  gap: var(--spacing-200);
  font-size: 1rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  flex-wrap: wrap;
  margin: 0;
  display: flex;
}
.step__when {
  font-size: 0.875rem;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-secondary);
}
.step__text {
  color: var(--color-content-default-secondary);
  margin: 0;
  font-size: 0.9375rem;
  line-height: 1.5;
}
.step[data-state="scheduled"] .step__dot {
  border-color: var(--st-survey-scheduled);
}
.step[data-state="live-red"] .step__dot {
  border-color: var(--st-provisional-block);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--st-provisional-block) 18%, transparent);
}
.step[data-state="live-red"] .step__dot:after {
  content: "";
  border-radius: var(--radius-full);
  background: var(--st-provisional-block);
  width: 8px;
  height: 8px;
}
.step[data-state="live-red"] .step__when {
  color: color-mix(in srgb, var(--st-provisional-block) 72%, #1a1a1a);
}
.check {
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
}
.check__row {
  column-gap: var(--spacing-250);
  padding: var(--spacing-200) 0;
  grid-template-columns: 12px 1fr auto;
  align-items: center;
  row-gap: 2px;
  display: grid;
}
.check__dot {
  border-radius: var(--radius-full);
  justify-self: center;
  width: 10px;
  height: 10px;
}
.check__dim {
  font-size: 0.9375rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.check__state {
  color: var(--color-content-default-secondary);
  grid-column: 2/-1;
  font-size: 0.875rem;
}
.check__row + .check__row {
  border-top: 1px solid var(--color-border-default-subtle);
}
.check__dot[data-none="true"] {
  background: var(--color-background-elevation-raised);
  border: 1px dashed var(--color-border-default-strong);
}
.action--instep {
  padding: var(--spacing-300);
  margin-top: var(--spacing-250);
}
.action__text strong {
  color: color-mix(in srgb, var(--st-provisional-block) 72%, #1a1a1a);
  font-weight: var(--typography-font-weight-semibold);
}
.step[data-state="future"] .step__dot {
  border-style: dashed;
  border-color: var(--color-border-default-strong);
}
.step:last-child {
  padding-bottom: 0;
}
.step__flag {
  align-items: flex-start;
  gap: var(--spacing-150);
  font-size: 0.9375rem;
  font-weight: var(--typography-font-weight-semibold);
  color: color-mix(in srgb, var(--st-blocked) 72%, #1a1a1a);
  margin: 0;
  line-height: 1.45;
  display: flex;
}
.step__flag .esa-icon {
  flex-shrink: 0;
  margin-top: 2px;
}
.step__act {
  gap: var(--spacing-200);
  margin-top: var(--spacing-100);
  display: flex;
}
.survey__link {
  font-size: 0.9375rem;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-background-brand-muted);
  cursor: pointer;
  text-decoration: none;
}
.step[data-state="live"] .step__dot {
  border-color: var(--st-survey-scheduled);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--st-survey-scheduled) 22%, transparent);
}
.step[data-state="live"] .step__dot:after {
  content: "";
  border-radius: var(--radius-full);
  background: var(--st-survey-scheduled);
  width: 8px;
  height: 8px;
}
.check__act {
  grid-area: 1/3;
}
.esa-icon {
  --_icon-size: var(--icon-size-md, 20px);
  width: var(--_icon-size);
  height: var(--_icon-size);
  color: inherit;
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.esa-icon--sm {
  --_icon-size: var(--icon-size-sm, 16px);
}
.esa-icon svg {
  width: var(--_icon-size);
  height: var(--_icon-size);
  display: block;
}
html,
.modern-layout__content {
  scroll-behavior: smooth;
}
